import {checkedUpdate} from './document-writes.mjs';
// Remove only effects generated by the retired character-specific runtime, preserving a recoverable copy first.
export async function retireRedlineEffects(actor){
 const effects=[...(actor.effects??[])].filter(effect=>effect.getFlag('vitruviy','redlineEffect'));
 if(!effects.length)return 0;
 const archive={...(actor.getFlag('vitruviy','retiredRedlineEffects')??{})};
 for(const effect of effects)archive[effect.id]=effect.toObject();
 await checkedUpdate(actor,{'flags.vitruviy.retiredRedlineEffects':archive});
 const deleted=await actor.deleteEmbeddedDocuments('ActiveEffect',effects.map(effect=>effect.id));
 if(deleted?.length!==effects.length)throw Error(game.i18n.localize('VIT.UpdateCancelled'));
 return deleted.length;
}
export async function retireRedlineWorld(){
 if(game.users.activeGM?.id!==game.user.id)return;
 const actors=new Map([...game.actors].map(actor=>[actor.uuid,actor]));
 for(const scene of game.scenes)for(const token of scene.tokens)if(token.actor)actors.set(token.actor.uuid,token.actor);
 for(const actor of actors.values())await retireRedlineEffects(actor);
}
